-- Fakt kartochkalari orqa tomonining ruscha matni — 74-partiya:
-- Sakkokiy, Sayfi Saroyi, Shayboniyxon.

UPDATE fact_cards SET detail_ru = 'Имя Саккаки и годы его рождения и смерти науке неизвестны. Он жил и творил в XV веке в Самарканде. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2290;
UPDATE fact_cards SET detail_ru = 'Саккаки жил и творил в Самарканде в пору правления Халиль Султана (1405–1409) и Улугбека. Источник: Ziyouz.com.' WHERE id = 2291;
UPDATE fact_cards SET detail_ru = 'Саккаки — один из поэтов, положивших в узбекской словесности начало жанру касыды. Свои касыды он писал, посвящая их Ходже Мухаммаду Порсо, Халиль Султану, Улугбеку и Арслану Ходже Тархану. Источник: Ziyouz.com.' WHERE id = 2292;
UPDATE fact_cards SET detail_ru = 'В одной из своих касыд Саккаки величает Улугбека как милостивого к народу правителя, просветителя и великого учёного. В знаменитом бейте он гордится тем, что творит на тюркском языке: «Небу надо кружить годами, чтобы дать в руки такого тюркского поэта, как я, и такого мудрого государя, как ты». Источник: Ziyouz.com.' WHERE id = 2293;
UPDATE fact_cards SET detail_ru = 'В своих сочинениях Саккаки изображал человеческую любовь, мечты и желания, боли и печали, красоты природы; в его лирике проводятся мысли о справедливости против невежества и неразумия. Источник: Ziyouz.com.' WHERE id = 2294;
UPDATE fact_cards SET detail_ru = 'Газели и касыды Саккаки были собраны в диван, но полный список дивана до нас не дошёл. Списки дивана хранятся в Лондоне, в Британском музее, и в Институте востоковедения Академии наук Узбекистана (инв. 7685). Источник: Ziyouz.com.' WHERE id = 2295;
UPDATE fact_cards SET detail_ru = 'Саккаки обогатил узбекскую светскую лирику и по содержанию, и по форме; его творчество, как и творчество Лутфи, Гадаи и Атаи, сильно повлияло и на творчество Алишера Навои. Навои упоминал его в ряду зрелых мастеров тюркского слова. Источник: Ziyouz.com.' WHERE id = 2296;
UPDATE fact_cards SET detail_ru = 'Год смерти Саккаки науке неизвестен; он жил и творил в XV веке в Самарканде. Его имя сохранилось в истории узбекской классической словесности как имя одного из основоположников жанра касыды. Источник: Ziyouz.com.' WHERE id = 2297;

UPDATE fact_cards SET detail_ru = 'Сайфи Сараи родился в 1321 году в селении Сарыкамыш Хорезмской области. Он жил в Средней Азии в пору монгольского завоевания и был вынужден покинуть родину. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2298;
UPDATE fact_cards SET detail_ru = 'Покинув родину, Сайфи Сараи жил в городе Сарай в Золотой Орде, а затем в Египте и Турции. Жизнь его прошла в скитаниях. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2299;
UPDATE fact_cards SET detail_ru = 'В 1391 году Сайфи Сараи переложил «Гулистан» Саади на узбекский (тюркский) язык и создал наполовину самостоятельное философско-нравственное сочинение «Гулистони бит-турки». В это сочинение из восьми глав были добавлены новые рассказы, отражающие дух времени. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2300;
UPDATE fact_cards SET detail_ru = 'Поучительные рассказы в «Гулистони бит-турки» проповедуют такие достоинства, как справедливость, честность, верность и милосердие. В поэзии сочинителя нашли место и темы любви к родине, человеколюбия, достоинства человека, дружбы и любви. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2301;
UPDATE fact_cards SET detail_ru = 'Сайфи Сараи написал поэму «Сухайль и Гульдурсун» и переложил на узбекский язык сочинение «Синдбад-наме», однако этот перевод не сохранился. Рукопись поэмы «Сухайль и Гульдурсун» хранится в Институте востоковедения Академии наук Узбекистана. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2302;
UPDATE fact_cards SET detail_ru = 'Сайфи Сараи известен как лирический поэт, сочинитель касыд, эпический поэт и переводчик. Известны более десяти его газелей, касыд, кыта и рубаи. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2303;
UPDATE fact_cards SET detail_ru = 'Сайфи Сараи основательно овладел персидским и арабским языками, словесностью, историей и народными поэтическими традициями. Эти знания и помогли ему переложить «Гулистан» Саади на тюркский язык. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2304;
UPDATE fact_cards SET detail_ru = 'Сайфи Сараи умер в 1398 году в египетском городе Александрии. Единственная рукопись «Гулистони бит-турки» хранится в Лейденском университете в Голландии, а её фотокопия — в Институте востоковедения Академии наук Узбекистана. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 2305;

UPDATE fact_cards SET detail_ru = 'Мухаммад Шейбани-хан родился в 1451 году. Он был внуком Абулхайр-хана, хана кочевых узбеков; отцом его был Шах Будаг-султан, матерью — Кузи-бегим, а дед Абулхайр-хан дал ему прозвище Шахбахт. Источник: Ziyouz.com, раздел «Правители Узбекистана».' WHERE id = 2306;
UPDATE fact_cards SET detail_ru = 'В 1480 году Шейбани-хан восстановил государство кочевых узбеков. В 1487–1488 годах он занял города Сайрам, Отрар и Туркестан и укрепил своё положение. Источник: Ziyouz.com, раздел «Правители Узбекистана».' WHERE id = 2307;
UPDATE fact_cards SET detail_ru = 'В 1499 году Шейбани-хан занял Бухару без боя, а в 1500-м — Самарканд. В 1501 году он разбил Бабура на берегу реки Кухак, в 1503-м присоединил Ташкент и Шахрухию, в 1504-м — Фергану и объединил Мавераннахр в составе своей державы. Источник: Ziyouz.com, раздел «Правители Узбекистана».' WHERE id = 2308;
UPDATE fact_cards SET detail_ru = 'В 1505 году Шейбани-хан занял средоточие Хорезма — Ургенч, в 1506-м — Балх, а в 1507 году взял столицу Хорасана Герат. Источник: Ziyouz.com, раздел «Правители Узбекистана».' WHERE id = 2309;
UPDATE fact_cards SET detail_ru = 'В 1507 году Шейбани-хан провёл денежную реформу, велев чеканить новые серебряные монеты весом 5,2 грамма. В образовании дети с шести лет учились два года в школе, а в медресе — по трёхступенчатой системе, каждая ступень которой длилась восемь лет. Источник: Ziyouz.com, раздел «Правители Узбекистана».' WHERE id = 2310;
UPDATE fact_cards SET detail_ru = 'Шейбани-хан ввёл систему суюргала и распределил области между султанами и беками: Балх дал Султаншаху, Андижан — Махмуд-султану, Ташкент — Суюнходже. Земли и воды, брошенные из-за тяжести податей, были снова пущены в дело. Источник: Ziyouz.com, раздел «Правители Узбекистана».' WHERE id = 2311;
UPDATE fact_cards SET detail_ru = 'Шейбани-хан был одарённым поэтом, писавшим газели и рубаи, и основательно знал тюркский, персидский и арабский языки. В 1508 году он создал поэму «Бахр уль-худа», а единственная рукопись написанной им для сына Тимур-султана книги наставлений хранится в Турции. Источник: Ziyouz.com, раздел «Правители Узбекистана».' WHERE id = 2312;
UPDATE fact_cards SET detail_ru = 'Шейбани-хан погиб в 1510 году близ Мерва, в Тахрирабаде на берегу реки Мургаб, потерпев поражение от войска иранского шаха Исмаила Сефеви. Он погребён в самаркандском Баланд-Суфа. Источник: Ziyouz.com, раздел «Правители Узбекистана».' WHERE id = 2313;
